import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location
import FranchiseListAdmin from './FranchiseListAdmin';

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div className="admin-dashboard">
      <style>
        {`
          .admin-dashboard {
            font-family: Arial, sans-serif;
            background-color: #f9f9f9;
            padding: 20px;
          }

          .dashboard-header {
            text-align: center;
            margin-bottom: 20px;
          }

          .dashboard-header h1 {
            color: #333;
            font-size: 2.5rem;
          }

          .dashboard-actions {
            display: flex;
            justify-content: center;
            gap: 15px;
            margin-bottom: 30px;
          }

          .action-btn {
            padding: 10px 20px;
            font-size: 1rem;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: background-color 0.3s;
          }

          .action-btn:hover {
            background-color: #007bff;
            color: white;
          }

          .logout-btn {
            background-color: #dc3545;
            color: white;
          }

          .logout-btn:hover {
            background-color: #c82333;
          }

          .table-container {
            overflow-x: auto;
            margin-top: 30px;
          }

          .franchise-table {
            width: 100%;
            border-collapse: collapse;
            margin: 0 auto;
            table-layout: fixed;
          }

          .franchise-table th, .franchise-table td {
            padding: 12px;
            text-align: left;
            border-bottom: 1px solid #ddd;
          }

          .franchise-table th {
            background-color: #007bff;
            color: white;
            font-weight: bold;
          }

          .franchise-table tr:hover {
            background-color: #f1f1f1;
          }

          @media (max-width: 768px) {
            .dashboard-actions {
              flex-direction: column;
              align-items: center;
            }

            .action-btn {
              width: 100%;
              margin-bottom: 10px;
            }
          }
        `}
      </style>

      <header className="dashboard-header">
        <h1>Welcome to Admin Dashboard</h1>
      </header>

      <div className="dashboard-actions">
        <button className="action-btn" onClick={() => navigate('/create-user')}>Create User</button>
        <button className="action-btn" onClick={() => navigate('/exam-data')}>Manage Exam Data</button>
        <button className="action-btn logout-btn" onClick={handleLogout}>Logout</button>
      </div>

      {/* Franchise List Table */}
      <div className="table-container">
        <table className="franchise-table">
          <thead>
            <tr>
              <th>Franchise Name</th>
              <th>Location</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            <FranchiseListAdmin /> {/* Assuming this component provides the list of franchises */}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminDashboard;
